-- Replace the Breakfast Club theme with pixel shares that follow the product's calorie split.
-- STATUS: written 2026-11-10, NOT yet applied to production (rejsoyzhhukatdaebgtq).
--
-- The first version (20261110_puzzle_themes.sql) shared pixels out by goal grams (60/24/16). The product
-- rule is the calorie split itself: carbs 50% / fats 30% / protein 20% (frontend/src/utils/nutrition/nutrition.js),
-- so painted cells are now carbs ~50%, protein ~20%, fats ~30%. Same pictures, same names and slots.
--
-- Safe only while nobody has collected or is playing these puzzles yet; the guard below stops the
-- migration otherwise, because replacing the artwork would change their progress.
do $$
begin
  if exists (select 1 from public.user_collections where collection_type = 'Breakfast Club')
     or exists (select 1 from public.daily_home_data where puzzle_id like 'ai\_%') then
    raise exception 'Breakfast Club puzzles are already in use; do not replace them in place';
  end if;
end $$;

delete from public.collection_puzzles where collection_type = 'Breakfast Club';
delete from public.puzzle_themes where id = 'breakfast_club';   -- cascades to generated_puzzles

insert into public.puzzle_themes (id, title, description, type, puzzle_count, bg_color, published) values ('breakfast_club', 'Breakfast Club', 'Start your day right by completing daily nutrition challenges and collecting 6 delicious breakfast-themed puzzles. Each puzzle brings you closer to building a wholesome morning meal. Rise and shine with every nutritious bite!', 'collection', 6, '#D8E8E7', true);
